INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 15, 'theory', 'Network Diagnostics: ping, ss, tcpdump, and Wireshark');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 0, 'Ping to a website''s IP address succeeds, but ping to its name fails. Where should you look for the problem?', '["In the cable", "In the MTU", "In DNS: the resolver does not answer or the name is configured incorrectly", "In the certificate"]', 2, 'The network works (the address answers), so what breaks is the translation of the name into an address.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 1, 'In the ss output the service listens on 127.0.0.1:80, yet clients get a refusal. Why?', '["The service is bound only to the local address and is unreachable from outside", "Port 80 is reserved", "File descriptors ran out", "The service listens on UDP"]', 0, 'It needs the address 0.0.0.0 (or the interface address): then connections from outside will be accepted.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 2, 'In tcpdump you see only outgoing SYN packets and no replies at all. What does this mean?', '["The connection is established", "The port is closed: an RST would have come back", "The server is waiting for an ACK", "The handshake does not complete: the packet is lost or filtered along the way"]', 3, 'A closed port answers with RST; silence is a sign of a lost packet or a filter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 3, 'Small requests go through, but large responses hang. What should you check first?', '["The certificate expiry date", "The MTU along the path and the blocking of ICMP \"frag needed\"", "The DNS rules", "Disk speed"]', 1, 'A link with a smaller MTU plus ICMP filtering produces exactly this picture; the threshold shows up with ping -M do.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 4, 'What does an asterisk on one traceroute hop mean if the following hops answer?', '["Packets are being lost", "The path is broken", "The router does not send ICMP time exceeded but does forward packets", "The router is rebooting"]', 2, 'The later replies prove that packets do pass through this node.');
